func (f *EvidenceFact) historySupports(val float64) bool {
	if f == nil || !f.RetainHistory || len(f.History) == 0 {
		return false
	}
	h := f.History
	if len(h) > FactHistoryMaxEntries {
		h = h[len(h)-FactHistoryMaxEntries:]
	}
	for i := range h {
		if math.Abs(val-h[i].Value) < 1e-6 {
			return true
		}
	}
	return false
}

